#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;

    // O(1) front insertion (unlike vector)
    d.push_front(10);

    // O(1) back insertion
    d.push_back(20);

    // O(1) removal
    d.pop_front();

    // d memory use often shrinks after pop operations

    // O(N) operation: insertion in the middle
    d.insert(d.begin(), 5);

    // Note: d.capacity() does not exist, but memory segments are managed
}
